namespace sv_57c836f2732f4390a9024668856d1d2c.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@* Step indicator bar showing progress through the multi-step form *@

<nav class="step-indicator mb-4" aria-label="Application progress">
    <ol class="d-flex list-unstyled justify-content-between p-0 m-0">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var isCurrent = step == CurrentStep;
            var isCompleted = CompletedSteps.Contains(step);
            var isFuture = !isCurrent && !isCompleted;

            <li class="step-item flex-fill text-center @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")">
                @if (isCompleted)
                {
                    <button type="button" class="btn btn-link step-link p-0 text-decoration-none w-100" @onclick="() => OnStepClicked.InvokeAsync(step)">
                        <span class="step-circle bg-success text-white">✓</span>
                        <span class="step-label d-block small mt-1 text-success fw-semibold">@StepNames[i]</span>
                    </button>
                }
                else
                {
                    <div class="w-100">
                        <span class="step-circle @(isCurrent ? "bg-primary text-white" : "bg-secondary text-white opacity-50")">@step</span>
                        <span class="step-label d-block small mt-1 @(isCurrent ? "text-primary fw-semibold" : "text-muted")">@StepNames[i]</span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter, EditorRequired]
    public int CurrentStep { get; set; }

    [Parameter, EditorRequired]
    public HashSet<int> CompletedSteps { get; set; } = [];

    [Parameter]
    public EventCallback<int> OnStepClicked { get; set; }
}

.step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    font-size: 0.85rem;
    font-weight: 600;
}

.step-item.future {
    opacity: 0.5;
}

.step-link:focus {
    outline: 2px solid var(--bs-primary);
    outline-offset: 2px;
    border-radius: 0.25rem;
}

@* Editor for a single work history entry *@

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Position @Index</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name</label>
                <input type="text" class="form-control" value="@Entry.Company"
                       @onchange="e => Update(Entry with { Company = (string?)e.Value ?? "" })" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title</label>
                <input type="text" class="form-control" value="@Entry.Title"
                       @onchange="e => Update(Entry with { Title = (string?)e.Value ?? "" })" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date</label>
                <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                       @onchange="e => Update(Entry with { StartDate = DateTime.TryParse((string?)e.Value, out var d) ? d : Entry.StartDate })" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@Entry.EndDate?.ToString("yyyy-MM-dd")"
                       disabled="@IsCurrent"
                       @onchange="e => Update(Entry with { EndDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null })" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input type="checkbox" class="form-check-input" id="@($"current-{Index}")" checked="@IsCurrent"
                           @onchange="OnCurrentChanged" />
                    <label class="form-check-label" for="@($"current-{Index}")">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@Entry.Description"
                          @onchange="e => Update(Entry with { Description = (string?)e.Value ?? "" })"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public WorkEntry Entry { get; set; } = default!;

    [Parameter]
    public int Index { get; set; }

    [Parameter]
    public bool CanRemove { get; set; }

    [Parameter]
    public EventCallback<WorkEntry> OnChanged { get; set; }

    [Parameter]
    public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null;

    private void Update(WorkEntry updated) => OnChanged.InvokeAsync(updated);

    private void OnCurrentChanged(ChangeEventArgs e)
    {
        bool current = (bool)(e.Value ?? false);
        Update(Entry with { EndDate = current ? null : DateTime.Today });
    }
}

@* Editor for a single reference entry *@

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Reference @Index</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Name</label>
                <input type="text" class="form-control" value="@Reference.Name"
                       @onchange="e => Update(Reference with { Name = (string?)e.Value ?? "" })" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship</label>
                <input type="text" class="form-control" value="@Reference.Relationship"
                       @onchange="e => Update(Reference with { Relationship = (string?)e.Value ?? "" })" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" value="@Reference.Email"
                       @onchange="e => Update(Reference with { Email = (string?)e.Value ?? "" })" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone</label>
                <input type="tel" class="form-control" value="@Reference.Phone"
                       @onchange="e => Update(Reference with { Phone = (string?)e.Value ?? "" })" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Reference Reference { get; set; } = default!;

    [Parameter]
    public int Index { get; set; }

    [Parameter]
    public bool CanRemove { get; set; }

    [Parameter]
    public EventCallback<Reference> OnChanged { get; set; }

    [Parameter]
    public EventCallback OnRemove { get; set; }

    private void Update(Reference updated) => OnChanged.InvokeAsync(updated);
}

@* Step 1: Personal information *@

<div>
    <h4 class="mb-3">Personal Information</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Full Name <span class="text-danger">*</span></label>
            <input type="text" class="form-control @ValidationClass(Personal.FullName)" value="@Personal.FullName"
                   @onchange="e => Update(Personal with { FullName = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Email <span class="text-danger">*</span></label>
            <input type="email" class="form-control @ValidationClass(Personal.Email)" value="@Personal.Email"
                   @onchange="e => Update(Personal with { Email = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Phone <span class="text-danger">*</span></label>
            <input type="tel" class="form-control @ValidationClass(Personal.Phone)" value="@Personal.Phone"
                   @onchange="e => Update(Personal with { Phone = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Address <span class="text-danger">*</span></label>
            <input type="text" class="form-control @ValidationClass(Personal.Address)" value="@Personal.Address"
                   @onchange="e => Update(Personal with { Address = (string?)e.Value ?? "" })" />
        </div>
    </div>

    <div class="d-flex justify-content-end mt-4">
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status" aria-hidden="true"></span>
                <text>Validating…</text>
            }
            else
            {
                <text>Next</text>
            }
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public PersonalInfo Personal { get; set; } = default!;

    [Parameter]
    public EventCallback<PersonalInfo> OnChanged { get; set; }

    [Parameter]
    public EventCallback OnNext { get; set; }

    [Parameter]
    public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private bool IsValidating;
    private bool _attempted;

    private void Update(PersonalInfo updated) => OnChanged.InvokeAsync(updated);

    private string ValidationClass(string value) =>
        _attempted && string.IsNullOrWhiteSpace(value) ? "is-invalid" : "";

    private async Task HandleNext()
    {
        _attempted = true;
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Personal.FullName) ||
            string.IsNullOrWhiteSpace(Personal.Email) ||
            string.IsNullOrWhiteSpace(Personal.Phone) ||
            string.IsNullOrWhiteSpace(Personal.Address))
        {
            ErrorMessage = "Please fill in all required fields.";
            return;
        }

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            try
            {
                var isValid = await ValidateEmail(Personal.Email);
                if (!isValid)
                {
                    ErrorMessage = "The email address could not be validated. Please check and try again.";
                    return;
                }
            }
            finally
            {
                IsValidating = false;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@* Step 2: Work history with dynamic entries *@

<div>
    <h4 class="mb-3">Work History</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryEditor Entry="@Entries[index]"
                         Index="@(index + 1)"
                         CanRemove="@(Entries.Count > 1)"
                         OnChanged="e => UpdateEntry(index, e)"
                         OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-secondary mb-4" @onclick="AddEntry">
        + Add Another Position
    </button>

    <div class="d-flex justify-content-between mt-2">
        <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<WorkEntry> Entries { get; set; } = [];

    [Parameter]
    public EventCallback<List<WorkEntry>> OnChanged { get; set; }

    [Parameter]
    public EventCallback OnNext { get; set; }

    [Parameter]
    public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateEntry(int index, WorkEntry updated)
    {
        var list = new List<WorkEntry>(Entries) { [index] = updated };
        OnChanged.InvokeAsync(list);
    }

    private void RemoveEntry(int index)
    {
        var list = new List<WorkEntry>(Entries);
        list.RemoveAt(index);
        OnChanged.InvokeAsync(list);
    }

    private void AddEntry()
    {
        var list = new List<WorkEntry>(Entries)
        {
            new("", "", DateTime.Today, null, "")
        };
        OnChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        var first = Entries[0];
        if (string.IsNullOrWhiteSpace(first.Company) || string.IsNullOrWhiteSpace(first.Title))
        {
            ErrorMessage = "Please complete at least one work entry with company name and job title.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@* Step 3: References (2-3) *@

<div>
    <h4 class="mb-3">References</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceEditor Reference="@References[index]"
                         Index="@(index + 1)"
                         CanRemove="@(References.Count > 2)"
                         OnChanged="e => UpdateReference(index, e)"
                         OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-secondary mb-4" @onclick="AddReference">
            + Add Reference
        </button>
    }

    <div class="d-flex justify-content-between mt-2">
        <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<Reference> References { get; set; } = [];

    [Parameter]
    public EventCallback<List<Reference>> OnChanged { get; set; }

    [Parameter]
    public EventCallback OnNext { get; set; }

    [Parameter]
    public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateReference(int index, Reference updated)
    {
        var list = new List<Reference>(References) { [index] = updated };
        OnChanged.InvokeAsync(list);
    }

    private void RemoveReference(int index)
    {
        var list = new List<Reference>(References);
        list.RemoveAt(index);
        OnChanged.InvokeAsync(list);
    }

    private void AddReference()
    {
        if (References.Count >= 3) return;
        var list = new List<Reference>(References)
        {
            new("", "", "", "")
        };
        OnChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (References.Any(r => string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email)))
        {
            ErrorMessage = "Please provide at least a name and email for each reference.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@* Step 4: Cover letter with character count *@

<div>
    <h4 class="mb-3">Cover Letter</h4>

    <div class="mb-2">
        <textarea class="form-control" rows="12" maxlength="@MaxLength"
                  value="@CoverLetter"
                  @onchange="e => OnChanged.InvokeAsync((string?)e.Value ?? "")"></textarea>
    </div>
    <div class="text-muted small text-end mb-4">
        @(CoverLetter?.Length ?? 0) / @MaxLength characters
    </div>

    <div class="d-flex justify-content-between">
        <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="OnNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter]
    public string CoverLetter { get; set; } = "";

    [Parameter]
    public EventCallback<string> OnChanged { get; set; }

    [Parameter]
    public EventCallback OnNext { get; set; }

    [Parameter]
    public EventCallback OnBack { get; set; }
}

@* Step 5: Review all data and submit *@

<div>
    <h4 class="mb-3">Review &amp; Submit</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @* Personal Info *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Personal Information</strong>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-3">Name</dt>
                <dd class="col-sm-9">@Personal.FullName</dd>
                <dt class="col-sm-3">Email</dt>
                <dd class="col-sm-9">@Personal.Email</dd>
                <dt class="col-sm-3">Phone</dt>
                <dd class="col-sm-9">@Personal.Phone</dd>
                <dt class="col-sm-3">Address</dt>
                <dd class="col-sm-9">@Personal.Address</dd>
            </dl>
        </div>
    </div>

    @* Work History *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Work History</strong>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var entry in WorkEntries)
            {
                <div class="mb-3">
                    <strong>@entry.Title</strong> at @entry.Company<br />
                    <span class="text-muted small">
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="mt-1 mb-0">@entry.Description</p>
                    }
                </div>
            }
        </div>
    </div>

    @* References *@
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>References</strong>
            <button type="button" class="btn btn-link btn-sm p-0" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
        </div>
        <div class="card-body">
