{"path": "/tmp/sv-57c836f2732f4390a9024668856d1d2c/Components/Pages/Application/PersonalInfoStep.razor", "file_text": "@* Step 1: Personal information *@

<div>
    <h4 class="mb-3">Personal Information</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Full Name <span class="text-danger">*</span></label>
            <input type="text" class="form-control @ValidationClass(Personal.FullName)" value="@Personal.FullName"
                   @onchange="e => Update(Personal with { FullName = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Email <span class="text-danger">*</span></label>
            <input type="email" class="form-control @ValidationClass(Personal.Email)" value="@Personal.Email"
                   @onchange="e => Update(Personal with { Email = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Phone <span class="text-danger">*</span></label>
            <input type="tel" class="form-control @ValidationClass(Personal.Phone)" value="@Personal.Phone"
                   @onchange="e => Update(Personal with { Phone = (string?)e.Value ?? "" })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Address <span class="text-danger">*</span></label>
            <input type="text" class="form-control @ValidationClass(Personal.Address)" value="@Personal.Address"
                   @onchange="e => Update(Personal with { Address = (string?)e.Value ?? "" })" />
        </div>
    </div>

    <div class="d-flex justify-content-end mt-4">
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status" aria-hidden="true"></span>
                <text>Validating…</text>
            }
            else
            {
                <text>Next</text>
            }
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public PersonalInfo Personal { get; set; } = default!;

    [Parameter]
    public EventCallback<PersonalInfo> OnChanged { get; set; }

    [Parameter]
    public EventCallback OnNext { get; set; }

    [Parameter]
    public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private bool IsValidating;
    private bool _attempted;

    private void Update(PersonalInfo updated) => OnChanged.InvokeAsync(updated);

    private string ValidationClass(string value) =>
        _attempted && string.IsNullOrWhiteSpace(value) ? "is-invalid" : "";

    private async Task HandleNext()
    {
        _attempted = true;
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Personal.FullName) ||
            string.IsNullOrWhiteSpace(Personal.Email) ||
            string.IsNullOrWhiteSpace(Personal.Phone) ||
            string.IsNullOrWhiteSpace(Personal.Address))
        {
            ErrorMessage = "Please fill in all required fields.";
            return;
        }

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            try
            {
                var isValid = await ValidateEmail(Personal.Email);
                if (!isValid)
                {
                    ErrorMessage = "The email address could not be validated. Please check and try again.";
                    return;
                }
            }
            finally
            {
                IsValidating = false;
            }
        }

        await OnNext.InvokeAsync();
    }
}
"}

{"path": "/tmp/sv-57c836f2732f4390a9024668856d1d2c/Components/Pages/Application/WorkHistoryStep.razor", "file_text": "@* Step 2: Work history with dynamic entries *@

<div>
    <h4 class="mb-3">Work History</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryEditor Entry="@Entries[index]"
                         Index="@(index + 1)"
                         CanRemove="@(Entries.Count > 1)"
                         OnChanged="e => UpdateEntry(index, e)"
                         OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-secondary mb-4" @onclick="AddEntry">
        + Add Another Position
    </button>

    <div class="d-flex justify-content-between mt-2">
        <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<WorkEntry> Entries { get; set; } = [];

    [Parameter]
    public EventCallback<List<WorkEntry>> OnChanged { get; set; }

    [Parameter]
    public EventCallback OnNext { get; set; }

    [Parameter]
    public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateEntry(int index, WorkEntry updated)
    {
        var list = new List<WorkEntry>(Entries) { [index] = updated };
        OnChanged.InvokeAsync(list);
    }

    private void RemoveEntry(int index)
    {
        var list = new List<WorkEntry>(Entries);
        list.RemoveAt(index);
        OnChanged.InvokeAsync(list);
    }

    private void AddEntry()
    {
        var list = new List<WorkEntry>(Entries)
        {
            new("", "", DateTime.Today, null, "")
        };
        OnChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        var first = Entries[0];
        if (string.IsNullOrWhiteSpace(first.Company) || string.IsNullOrWhiteSpace(first.Title))
        {
            ErrorMessage = "Please complete at least one work entry with company name and job title.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}
"}

{"path": "/tmp/sv-57c836f2732f4390a9024668856d1d2c/Components/Pages/Application/ReferencesStep.razor", "file_text": "@* Step 3: References (2-3) *@

<div>
    <h4 class="mb-3">References</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceEditor Reference="@References[index]"
                         Index="@(index + 1)"
                         CanRemove="@(References.Count > 2)"
                         OnChanged="e => UpdateReference(index, e)"
                         OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-secondary mb-4" @onclick="AddReference">
            + Add Reference
        </button>
    }

    <div class="d-flex justify-content-between mt-2">
        <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<Reference> References { get; set; } = [];

    [Parameter]
    public EventCallback<List<Reference>> OnChanged { get; set; }

    [Parameter]
    public EventCallback OnNext { get; set; }

    [Parameter]
    public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateReference(int index, Reference updated)
    {
        var list = new List<Reference>(References) { [index] = updated };
        OnChanged.InvokeAsync(list);
    }

    private void RemoveReference(int index)
    {
        var list = new List<Reference>(References);
        list.RemoveAt(index);
        OnChanged.InvokeAsync(list);
    }

    private void AddReference()
    {
        if (References.Count >= 3) return;
        var list = new List<Reference>(References)
        {
            new("", "", "", "")
        };
        OnChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (References.Any(r => string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email)))
        {
            ErrorMessage = "Please provide at least a name and email for each reference.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}
"}

