namespace sv_57c836f2732f4390a9024668856d1d2c.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@using sv_57c836f2732f4390a9024668856d1d2c.Models
@using sv_57c836f2732f4390a9024668856d1d2c.Components.Pages.Application
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (_submitted)
    {
        <div class="alert alert-success text-center py-5">
            <h3 class="mb-3">🎉 Application Submitted!</h3>
            <p class="lead">Your application has been received.</p>
            <p>Your application ID is: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="@_currentStep"
                       CompletedSteps="@_completedSteps"
                       OnStepClicked="GoToStep" />

        <div class="mt-4">
            @switch (_currentStep)
            {
                case 1:
                    <PersonalInfoStep Personal="@_personal"
                                      OnChanged="p => _personal = p"
                                      OnNext="CompleteAndAdvance"
                                      ValidateEmail="ApplicationService.ValidateEmailAsync" />
                    break;

                case 2:
                    <WorkHistoryStep Entries="@_workEntries"
                                     OnChanged="e => _workEntries = e"
                                     OnNext="CompleteAndAdvance"
                                     OnBack="GoBack" />
                    break;

                case 3:
                    <ReferencesStep References="@_references"
                                    OnChanged="r => _references = r"
                                    OnNext="CompleteAndAdvance"
                                    OnBack="GoBack" />
                    break;

                case 4:
                    <CoverLetterStep CoverLetter="@_coverLetter"
                                     OnChanged="c => _coverLetter = c"
                                     OnNext="CompleteAndAdvance"
                                     OnBack="GoBack" />
                    break;

                case 5:
                    <ReviewStep Personal="@_personal"
                                WorkEntries="@_workEntries"
                                References="@_references"
                                CoverLetter="@_coverLetter"
                                OnEditSection="GoToStep"
                                OnSubmit="SubmitApplication"
                                OnBack="GoBack" />
                    break;
            }
        </div>
    }
</div>

@code {
    private int _currentStep = 1;
    private readonly HashSet<int> _completedSteps = [];
    private bool _submitted;
    private int _applicationId;

    private PersonalInfo _personal = new("", "", "", "");
    private List<WorkEntry> _workEntries = [new("", "", DateTime.Today, null, "")];
    private List<Reference> _references = [new("", "", "", ""), new("", "", "", "")];
    private string _coverLetter = "";

    private void CompleteAndAdvance()
    {
        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private void GoBack() => _currentStep--;

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step) || step == _currentStep)
        {
            _currentStep = step;
        }
    }

    private async Task SubmitApplication()
    {
        var application = new JobApplication(
            _personal,
            new WorkHistory(_workEntries),
            _references,
            _coverLetter
        );

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _submitted = true;
    }
}

