private void Update(WorkEntry updated) => OnChanged.InvokeAsync(updated);

private void OnCompanyChanged(ChangeEventArgs e) =>
    Update(new WorkEntry((string?)e.Value ?? "", Entry.Title, Entry.StartDate, Entry.EndDate, Entry.Description));

private void OnTitleChanged(ChangeEventArgs e) =>
    Update(new WorkEntry(Entry.Company, (string?)e.Value ?? "", Entry.StartDate, Entry.EndDate, Entry.Description));

private void OnStartDateChanged(ChangeEventArgs e) =>
    Update(new WorkEntry(Entry.Company, Entry.Title, DateTime.TryParse((string?)e.Value, out var d) ? d : Entry.StartDate, Entry.EndDate, Entry.Description));

